// Applies a sector's partner requirements to the screening policy and reports what moved.
async function activateSector(sector){const before=new Map(results.map(a=>[a.key,a.status]));const req=sector.partnerRequirements||{};const settings={...state.settings,minInvestment:req.minInvestmentLakh,minArea:req.minAreaSqFt,minLaunch:req.minLaunchMonths,targetLaunch:req.targetLaunchMonths,sector:sector.id,sectorName:sector.name,sectorVersion:sector.version||0};const errors=E.policyErrors(settings);if(errors.length)throw Error('Sector requirements are incomplete: '+errors.join(' '));const after=E.assess(state.apps,state.territories,stores,state.reference,settings);const moved=after.filter(a=>before.has(a.key)&&before.get(a.key)!==a.status);pendingChat=null;state.settings=settings;sectorList=null;audit(`Activated sector ${sector.name}${sector.version?' v'+sector.version:''}; partner requirements, score weights and potential revenue now follow it.`);save();calculate();return{lines:[`${moved.length} applicant${moved.length===1?'':'s'} change${moved.length===1?'s':''} status${moved.length?': '+moved.slice(0,4).map(a=>`${a.id} ${before.get(a.key)} → ${a.status}`).join('; ')+(moved.length>4?'; …':''):''}`]};}
// Saves edited scoring logic (weights, filters, grade bands) and reports applicants whose status or grade moved.
function saveScoringPolicy(next,changes){const errors=E.policyErrors(next);if(errors.length){toast(errors.join(' '));return;}pendingChat=null;state.settings=next;const statusCount=changes.filter(c=>c.status[0]!==c.status[1]).length,gradeCount=changes.filter(c=>c.grade[0]!==c.grade[1]).length;audit(`Changed scoring logic: ${statusCount} applicant${statusCount===1?'':'s'} change status, ${gradeCount} change grade.`);save();lastScoringChange=changes;render();toast(`Scoring logic saved. ${statusCount} status change${statusCount===1?'':'s'}, ${gradeCount} grade change${gradeCount===1?'':'s'}.`);}
// Built-in default: apparel requirements, weights, grade bands and filters. Also returns the active sector to apparel.
function resetScoringPolicy(){const before=results;state.settings=JSON.parse(JSON.stringify(E.defaultPolicy));pendingChat=null;const after=E.assess(state.apps,state.territories,stores,state.reference,state.settings);lastScoringChange=E.compareResults(before,after);audit('Reset scoring logic to the built-in default.');save();render();toast('Scoring logic reset to the built-in default.');}
async function switchSector(id){const list=await loadSectors(),sector=list.find(s=>s.id===id),previous=list.find(s=>s.id===activeSectorId())||list[0];if(!sector)return;try{const impact=await activateSector(sector);const lines=[...(window.SectorStudio?SectorStudio.describeChanges(previous,sector):[]),...impact.lines];lastSectorChange={title:`${sector.name} is now the active sector`,lines};render();toast(`${sector.name} active. ${lines.slice(0,3).join('; ')}.`);}catch(error){toast(error.message);}} let territoriesView=null,pendingExpansionFocus=null; function openExpansionArea(id){pendingExpansionFocus=id;if(tab==='expansion'){expansionMap?.selectGeography(id);pendingExpansionFocus=null;return;}tab='expansion';location.hash='expansion';render();}
