async function loadMarket(){
 const refreshActiveScreen=()=>{if(tab==='market')render();else if(tab==='screening'&&territoryScreening)territoryScreening.updateMarketContext(screeningContextFor(screeningSelectedLocation));};
 try{
  const [sources,benchmarks,rows]=await Promise.all([marketRequest('/api/market/sources'),marketRequest('/api/market/benchmarks'),marketRequest(`/api/market/assessments?workspaceId=${encodeURIComponent(persistence.workspaceId)}`)]);
  marketSources=sources.sources||[];marketBenchmarks=benchmarks.observations||[];marketAssessments=rows.assessments||[];refreshActiveScreen();
 }catch{
  try{const [sources,benchmarks]=await Promise.all([marketRequest('/api/market/sources'),marketRequest('/api/market/benchmarks')]);marketSources=sources.sources||[];marketBenchmarks=benchmarks.observations||[];}catch{}
  refreshActiveScreen();
 }
}
