async function runMarketForecast(){const form=$('#market-form'),active=marketAssessments.find(a=>a.id===document.body.dataset.marketAssessment)||marketAssessments[0];if(!active||!form){toast('Save this location before running store scenarios.');return;}const get=name=>marketNum(form,name),required=['investment','workingCapital','areaSqFt','fixedCosts','grossMargin','royaltyRate','aov','conversionRate','salesRampMonths','initialRampFraction','years','annualNominalGrowth','annualInflation','discountRate'];const missing=required.filter(name=>get(name)===undefined);if(missing.length){toast('Enter the required store and forecast assumptions before running scenarios.');form.elements[missing[0]].focus();return;}const store={initialInvestment:get('investment'),workingCapital:get('workingCapital'),areaSqFt:get('areaSqFt'),monthlyFixedCosts:get('fixedCosts'),grossMargin:get('grossMargin'),royaltyRate:get('royaltyRate'),aov:get('aov'),conversionRate:get('conversionRate'),salesRampMonths:get('salesRampMonths'),initialRampFraction:get('initialRampFraction'),...(get('monthlyPassingPedestrianTraffic')!==undefined?{monthlyPassingPedestrianTraffic:get('monthlyPassingPedestrianTraffic')}:{ }),...(get('entryRate')!==undefined?{entryRate:get('entryRate')}:{ })},forecast={years:get('years'),annualNominalGrowth:get('annualNominalGrowth'),annualInflation:get('annualInflation'),discountRate:get('discountRate')},scoreKeys={demand:'scoreDemand',purchasingPower:'scorePurchasingPower',competition:'scoreCompetition',accessibility:'scoreAccessibility',financial:'scoreFinancial',growth:'scoreGrowth'},scoreMetrics=Object.fromEntries(Object.entries(scoreKeys).filter(([,field])=>get(field)!==undefined).map(([key,field])=>[key,get(field)]));if(!Object.keys(scoreMetrics).length)Object.assign(scoreMetrics,{});const payload={sector:activeSectorId(),store,market:{samAnnual:active.snapshot?.results?.metrics?.sam?.value,captureBenchmark:active.snapshot?.inputs?.segmentation?.captureRate},forecast,scenarioFactors:{conservative:0.75,base:1,optimistic:1.25},...(Object.keys(scoreMetrics).length?{scoreMetrics}:{})};try{let result=await marketRequest('/api/market/forecast',{method:'POST',body:JSON.stringify(payload)});const conservative=result.economics?.scenarios?.conservative;const downsideCashFlowNegative=Array.isArray(conservative?.months)&&conservative.months.some(row=>typeof row.operatingCashFlow==='number'&&row.operatingCashFlow<0);const criticalEvidenceMissing=!active.snapshot?.results?.metrics?.tam?.value||!active.snapshot?.sourceVersions?.length;if(payload.scoreMetrics&&(downsideCashFlowNegative||criticalEvidenceMissing))result=await marketRequest('/api/market/forecast',{method:'POST',body:JSON.stringify({...payload,scoreGates:{downsideCashFlowNegative,criticalEvidenceMissing}})});const latest=marketAssessments.find(a=>a.id===active.id)||active,snapshot={...latest.snapshot,forecast:result,forecastInputs:payload,forecastProvenance:{modelVersion:result.modelVersion,evidenceClass:'user_assumption',sourceVersions:latest.snapshot.sourceVersions||[],inputNote:'Store and forecast fields entered by the user; scenario factors are configured model cases.'}};const saved=await marketRequest(`/api/market/assessments/${active.id}`,{method:'PUT',body:JSON.stringify({workspaceId:persistence.workspaceId,expectedVersion:latest.version,snapshot})});marketAssessments=marketAssessments.map(a=>a.id===active.id?{...a,version:saved.version,snapshot}:a);document.body.dataset.marketAssessment=active.id;toast('Server forecast calculated and saved with its input provenance.');render();}catch(error){toast(`Forecast unavailable: ${error.message}`);}}
function table(rows,compact=false){if(!rows.length)return `<div class="empty"><h2>No applications here yet</h2>Upload a workbook or change your filters.</div>`;return `<div class="table-wrap"><table><thead><tr><th>Applicant</th><th>Location</th><th>Score range</th><th>Status</th>${compact?'':'<th>Next action</th>'}<th></th></tr></thead><tbody>${rows.map(a=>`<tr class="clickable" data-detail="${esc(a.key)}" tabindex="0" role="button" aria-label="Open ${esc(a.name||a.id||a.key)}"><td><div class="person"><div class="avatar">${esc((a.name||'?').split(/\s+/).slice(0,2).map(n=>n[0]).join(''))}</div><div><strong>${esc(a.name||'Name missing')}</strong><span class="sub">${esc(a.id||'ID missing')}</span></div></div></td><td>${esc(a.city||'City missing')}<span class="sub">${esc(a.pin||'Pin missing')}</span></td><td><span class="score">${a.grade?'<span class="grade">'+a.grade+'</span> ':''}${a.score}${a.high>a.score?'–'+a.high:''} <small>/100</small></span><span class="score-line"><i style="width:${a.score}%"></i></span></td><td>${statusTag(a)}</td>${compact?'':`<td><span class="small-text muted">${esc(nextAction(a))}</span></td>`}<td class="muted">↗</td></tr>`).join('')}</tbody></table></div>`;}
function nextAction(a){return {'Recommended':'Verify funding and site','Clarification needed':a.pending.length?'Confirm data corrections':a.missing.length?'Complete missing information':'Resolve conflicting information','Site needed':'Confirm site and floor','Territory review':'Resolve territory mapping','Location unavailable':'Choose another pin code','Waitlisted':'Review competing applications','Timeline review':'Agree a feasible launch date','Requirements not met':'Review funding or site size','Policy needed':'Configure brand requirements'}[a.status]||'Review application';}
// Overview insights. Each figure is counted from this workspace; anything not yet recorded says so instead of showing a number.
const MINUTES_PER_MANUAL_SCREEN=10, RAMP_MONTHS_BASE=6;
function onboardingInsights(){
 const done=state.taskDone||{},days=[];
 for(const a of results){const d=done[a.key]||{};if(completed(a)===7&&d[0]&&d[6]){const span=(Date.parse(d[6])-Date.parse(d[0]))/864e5;if(Number.isFinite(span)&&span>=0)days.push(span);}}
 const hours=results.map(a=>state.training?.[a.key]).filter(h=>Number.isFinite(h));
 const mean=values=>values.reduce((t,v)=>t+v,0)/values.length;
 return {onboardDays:days.length?mean(days):null,onboarded:days.length,lmsHours:hours.length?mean(hours):null,trained:hours.length};
}
function insightCard(value,label,note,iconName,tone=''){return `<div class="stat"><div class="stat-label">${label}${icon(iconName)}</div><div class="stat-value${value===null?' stat-empty':''}">${value===null?'Not recorded':value}</div><div class="stat-note ${tone}">${note}</div></div>`;}
function overviewInsights(){
 const screened=results.length,recommended=results.filter(a=>a.category==='Recommended').length,dataRequired=results.filter(a=>a.category==='Data required').length,future=results.filter(a=>a.category==='Future expansion').length;
 const minutes=screened*MINUTES_PER_MANUAL_SCREEN,saved=minutes>=60?`${+(minutes/60).toFixed(1)} h`:`${minutes} min`;
 const confirmed=state.corrections||0,waiting=pendingCount(),o=onboardingInsights();
 return `<div class="stats stats-3">${[
  insightCard(screened,'Applications screened',`${saved} saved at ${MINUTES_PER_MANUAL_SCREEN} min per manual review`,'applications','green'),
  insightCard(screened-recommended,'Applications filtered out',`${dataRequired} data required · ${future} future expansion · ${recommended} recommended`,'review'),
  insightCard(confirmed,'Data corrections made',`Proposed when the workbook was cleaned on upload, then confirmed by you${waiting?` · ${waiting} waiting`:''}`,'upload'),
  insightCard(o.onboardDays===null?null:`${Math.round(o.onboardDays)} days`,'Average time to onboard',o.onboarded?`First checklist step to opening readiness · ${o.onboarded} partner${o.onboarded===1?'':'s'}`:'Shown once a partner completes all 7 onboarding steps','onboarding'),
  insightCard(o.lmsHours===null?null:`${+o.lmsHours.toFixed(1)} h`,'Average time on the LMS',o.trained?`Per partner · ${o.trained} partner${o.trained===1?'':'s'} with training hours`:'Enter hours on the training step of a partner’s checklist','assistant'),
  insightCard(`${RAMP_MONTHS_BASE} mo`,'Average time to reach potential','Planning assumption: base-case sales ramp in the store cost model, not observed store data','territories')
 ].join('')}</div>`;
}
function overview(){const rec=results.filter(a=>a.category==='Recommended').length,dataRequired=results.filter(a=>a.category==='Data required'),held=results.filter(a=>a.status==='Clarification needed').length,sites=results.filter(a=>a.status==='Site needed').length;if(demoHidden())return heading('YOUR EXPANSION, AT A GLANCE','A clearer path to your next store.','Demo data is hidden. Upload a workbook to see your own applications.',`<button class="button" id="demo-toggle-inline" data-show-demo>Show demo data</button><button class="button primary" data-tab="upload">${icon('upload')} Upload workbook</button>`)+overviewInsights();return heading('YOUR EXPANSION, AT A GLANCE','A clearer path to your next store.','Review the right partners. Resolve the gaps. Keep every opening moving.',`<span class="demo-tag">${isDemo()?'SYNTHETIC DEMO':'YOUR WORKBOOK'}</span><button class="button primary" data-tab="upload">${icon('upload')} Upload workbook</button>`)+overviewInsights()+`<div class="grid-main"><section class="panel"><div class="panel-top"><div><h2>A little attention. A lot of progress.</h2><div class="panel-subtitle">The next actions that keep applications moving.</div></div><span class="tag amber">${dataRequired.length} data required</span></div><div class="panel-body"><div class="attention-row"><div class="attention-symbol">✓</div><div><strong>Confirm proposed corrections</strong><p>${pendingCount()} values need a quick check before scoring.</p></div><button class="text-button" data-tab="review">Review →</button></div><div class="attention-row"><div class="attention-symbol">?</div><div><strong>Fill in the missing pieces</strong><p>${held} applications have incomplete or conflicting information.</p></div><button class="text-button" data-filter="Data required">View →</button></div><div class="attention-row"><div class="attention-symbol">⌖</div><div><strong>Confirm site details</strong><p>${sites} applications need a site or its floor confirmed.</p></div><button class="text-button" data-filter="Data required">View →</button></div><div class="insight"><strong>Good candidates don’t disappear because a field is blank.</strong>Incomplete applications remain visible. Their score range shows what is confirmed and what could change.</div></div></section><div><section class="panel"><div class="panel-top"><h2>The expansion pipeline</h2><span class="eyebrow">LIVE</span></div><div class="panel-body">${[['Applications received',results.length],['Recommended',rec],['Data required',dataRequired.length],['Future expansion',results.filter(a=>a.category==='Future expansion').length],['Opening checks complete',results.filter(a=>a.category==='Recommended'&&completed(a)===7).length]].map(([l,n])=>`<div class="funnel-row"><div class="funnel-head"><span>${l}</span><strong>${n}</strong></div><div class="bar"><span style="width:${results.length?n/results.length*100:0}%"></span></div></div>`).join('')}</div></section></div></div><section class="panel section-gap"><div class="panel-top"><div><h2>Partners worth a closer look</h2><div class="panel-subtitle">Recommended partners first, then applications with unresolved details.</div></div><button class="text-button" data-tab="applications">View all applications →</button></div>${table([...results].sort((a,b)=>(b.category==='Recommended')-(a.category==='Recommended')||b.score-a.score).slice(0,5),true)}</section><div class="grid-main section-gap"><section class="panel"><div class="panel-top"><h2>Recent activity</h2></div><div class="panel-body">${state.audit.length?state.audit.slice(0,3).map(a=>`<div class="activity-row">${esc(a.text)}<small>${new Date(a.at).toLocaleString()}</small></div>`).join(''):'<p class="muted small-text">Corrections, application updates and onboarding progress will appear here.</p>'}</div></section><div class="callout"><div class="eyebrow">DECISIONS, EXPLAINED</div><h2>Ask what’s holding a partner back.</h2><p>Get a clear reason, or propose an update and see what changes.</p><button class="button small" data-tab="assistant">Open decision assistant ↗</button></div></div>`;}
function applications(){let list=results.filter(a=>(!filter||a.category===filter)&&(!query||[a.id,a.name,a.city,a.pin].some(v=>String(v||'').toLowerCase().includes(query.toLowerCase())))).sort((a,b)=>b.score-a.score);return heading('PARTNER PIPELINE','Every application, accounted for.','Scores help you prioritise. Status tells you what can happen next.',`<button class="button primary" data-tab="upload">Upload workbook</button>`)+`<section class="panel"><div class="panel-top"><div><h2>Applications <span class="muted">${list.length}</span></h2><div class="panel-subtitle">Recorded-input score to possible score · click a partner to see the reasoning.</div></div></div><div class="table-toolbar"><input id="search" class="input search" placeholder="Search name, ID, city or pin…" value="${esc(query)}" aria-label="Search applications"><select id="status-filter" class="input" aria-label="Filter by status"><option value="">All categories</option>${E.categories.map(s=>`<option ${s===filter?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div id="app-table">${table(list)}</div></section><p class="hint">Tie-breaks: confirmed score, sooner stated launch, then application ID. Unknown score components never inflate the confirmed score.</p>`;}
function review(){let cards=[];for(let a of state.apps)for(let [i,p] of a.pending.entries())cards.push(`<div class="review-card"><div class="actions" style="justify-content:space-between"><div><strong>${esc(a.name||a.id||a.key)}</strong> <span class="sub">${esc(a.id)} · ${esc(E.labels[p.field])}</span></div><button class="text-button" data-detail="${esc(a.key)}">Open application ↗</button></div><div class="review-values"><div><small>ORIGINAL VALUE</small>${esc(p.raw)}</div><span class="muted">→</span><div><small>PROPOSED VALUE · ${esc(p.reason||E.labels[p.field])}</small><input class="input" id="correction-${esc(a.key)}-${i}" type="number" min="0" step="any" value="${esc(p.proposed??'')}" placeholder="Enter a confirmed number" aria-label="Confirmed ${esc(E.labels[p.field])}"></div></div><button class="button primary small" data-confirm-correction="${esc(a.key)}" data-index="${i}">Confirm correction</button> <button class="button small" data-reject-correction="${esc(a.key)}" data-index="${i}">Mark as missing</button></div>`);return heading('DATA QUALITY','Clean data. With your confirmation.','Original answers are preserved. Proposed changes take effect only when confirmed.')+`<section class="panel"><div class="panel-top"><h2>Proposed corrections</h2><span class="tag amber">${cards.length} awaiting confirmation</span></div>${cards.join('')||'<div class="empty"><h2>No corrections waiting</h2>Missing or contradictory information can still need review.</div>'}</section><section class="panel section-gap"><div class="panel-top"><h2>Applications needing clarification</h2></div>${table(results.filter(a=>a.status==='Clarification needed'),true)}</section>${state.warnings.length?`<div class="info-row warning">${state.warnings.map(esc).join('<br>')}</div>`:''}`;}
function territories(){return '<div id="territories-root"></div>';}
function completed(a){return Object.values(state.tasks[a.key]||{}).filter(Boolean).length;}
function onboarding(){let list=results.filter(a=>a.status==='Recommended'||completed(a)>0);return heading('OPENING READINESS','From a good fit to an open store.','Each partner gets a sequenced checklist. Complete prerequisites before moving forward.')+`<section class="panel"><div class="panel-top"><h2>Partner onboarding</h2><span class="tag green">${list.length} partners</span></div>${list.map(a=>`<div class="onboarding-summary"><div><strong>${esc(a.name)}</strong><span class="sub">${esc(a.id)} · ${esc(a.city)} · Training: ${esc(a.language||'Confirm language')}</span><div class="compact">${statusTag(a)}</div></div><div><span class="small-text muted">${completed(a)} of 7 steps complete</span><div class="bar compact"><span style="width:${completed(a)/7*100}%"></span></div></div><button class="button small" data-detail="${esc(a.key)}">Open checklist ↗</button></div>`).join('')||'<div class="empty"><h2>Your next opening starts here</h2>Recommended partners will appear with their verification and training plan.</div>'}</section><div class="info-row">Recommendations are provisional. Funding, site suitability and signed agreements are verified in the checklist. Training completion is recorded by the operator; this MVP does not provide a learning-management system.</div>`;}
function assistant(){let sample=results.find(a=>a.status==='Clarification needed')||results[0],id=sample?.id||'APP-012',other=results.find(a=>a.id&&a.id!==id)?.id;let prompts=['How are scores calculated?','Who should move forward?',`Why is ${id} on hold?`,`What information is missing for ${id}?`,`What if ${id} investment is 50 lakh?`,...(other?[`Compare ${id} and ${other}`]:[])];let selected=results.find(a=>a.key===botContext);return heading('FRANCHISE BOT','Understand the decision. Ask the next question.','Get reasons, request clarification, compare applicants or preview a change.')+`<div class="chat-layout"><section class="panel"><div class="panel-top"><div><h2>Franchise bot</h2><div class="panel-subtitle">${selected?'Talking about '+esc(selected.id)+' · follow-up questions can omit the ID':'Answers grounded in your current workbook'}</div></div><button class="text-button" id="clear-chat">New conversation</button></div><div class="chat-log" id="chat-log" role="log" aria-live="polite">${(chat.length?chat:[{text:'I can explain decisions, scoring and assumptions; compare partners; and draft clarification questions. Ask a what-if question to preview a change, or state an update to review before confirming.\n\nI use the workbook and the visible assessment policy. I will ask when a fact is ambiguous.',user:false}]).map(m=>`<div class="message ${m.user?'user':''}"><span class="message-author">${m.user?'You':'Franchise bot'}</span>${esc(m.text)}</div>`).join('')}${pendingChat?`<div class="message proposal"><strong>Confirm proposed update</strong><br>${esc(pendingChat.id)}<br>${Object.entries(pendingChat.patch).map(([f,v])=>`${esc(E.labels[f])}: ${esc(state.apps.find(a=>a.key===pendingChat.key)?.[f]??'Missing')} → ${esc(v)}`).join('<br>')}<div class="actions compact"><button class="button primary small" id="confirm-chat">Confirm & reassess</button><button class="button small" id="cancel-chat">Cancel</button></div></div>`:''}</div><form class="chat-input" id="chat-form"><input class="input" id="chat-text" placeholder="Ask why, compare partners, or describe an update…" aria-label="Message to decision assistant" required maxlength="3000"><button class="button primary">Send ↗</button></form></section><aside><section class="panel"><div class="panel-top"><h2>Try asking</h2></div><div class="panel-body">${prompts.map(p=>`<button class="prompt" data-prompt="${esc(p)}">${esc(p)} ↗</button>`).join('')}<p class="hint">Evidence-based, rules-driven replies. No external AI model or outside market data. Unclear facts are left for confirmation.</p></div></section></aside></div>`;}
function rules(){return heading('RESEARCH AND ASSESSMENT','Requirements first. Evidence before approval.','A proposed screening policy informed by published franchise-selection practice.')+'<div id="sector-root" class="sector-slot"></div><div id="scoring-root" class="sector-slot"></div>'+`<div class="settings-grid"><section class="panel"><div class="panel-top"><h2>Screening fit score</h2><span class="tag green">Version 2</span></div><div class="panel-body">${[['Declared financial adequacy',35,'35 × min(declared investment / configured requirement, 1)'],['Premises readiness',30,'Identified owned or rented site 15; area adequacy up to 15'],['Operator experience',25,'Retail experience up to 20; explicit previous business operation 5'],['Feasible launch plan',10,'Inside the configured window 10; later 5; too soon 0 and review']].map(([s,n,d])=>`<div class="weight-row"><strong>${s}</strong><strong>${n}%</strong></div><div class="bar"><span style="width:${n}%;background:#2c7359"></span></div><p class="hint">${d}</p>`).join('')}<p class="small-text muted">Retail experience anchors: 0 years = 0 points; under 1 year = 5; 1–under 3 years = 10; 3–under 5 years = 15; 5+ years = 20. These anchors and weights are proposed pilot choices.</p><div class="info-row">Owned and rented premises receive equal points. Funding and area stop earning additional points once the requirement is met. Floor must be clarified and assessed, with no generic ground-floor bonus.</div><p class="small-text muted">Proposed grades: A 80–100; B 65–below 80; C 50–below 65; D below 50. U means one or more scored inputs remain unknown. A grade never overrides a failed requirement or a location restriction.</p></div></section><section class="panel"><div class="panel-top"><h2>Illustrative retail profile</h2><span class="tag amber">Replace with brand policy</span></div><div class="panel-body"><p class="small-text muted">₹${esc(state.settings.minInvestment)} lakh, ${esc(state.settings.minArea)} sq ft and ${esc(state.settings.minLaunch)}–${esc(state.settings.targetLaunch)} months come from the active sector (${esc(state.settings.sectorName||'Apparel & fashion')}) and are demonstration assumptions for this unnamed brand. They are not Lenskart requirements or universal industry thresholds. Required investment should include setup costs and an explicit working-capital reserve agreed with the brand.</p><p class="small-text muted">Edit requirements, filters, weights and grade bands in <a href="#rules">Scoring logic</a> above.</p></div></section><section class="panel"><div class="panel-top"><h2>What the research establishes</h2></div><div class="panel-body"><p class="small-text muted">The reviewed sources support brand-specific financial capacity, site suitability, operator capability, due diligence and training. They do not establish one universal numerical grade. The score above is our proposed screening implementation; approval still requires a verified business case and human review.</p><p class="small-text"><a href="franchise-methodology.docx" download>Download research and methodology document ↓</a></p><ul class="help-list"><li><a href="https://www.bdc.ca/en/articles-tools/business-strategy-planning/manage-growth/how-select-potential-franchisees" target="_blank" rel="noopener">BDC and Canadian Franchise Association guidance</a></li><li><a href="https://www.wipo.int/edocs/pubdocs/en/sme/1035/wipo_pub_1035.pdf" target="_blank" rel="noopener">WIPO guide to franchising</a></li><li><a href="https://www.ftc.gov/business-guidance/resources/consumers-guide-buying-franchise" target="_blank" rel="noopener">FTC due-diligence guidance — United States</a></li><li><a href="https://journals.sagepub.com/doi/10.1177/097226290901300104" target="_blank" rel="noopener">Saraogi 2009 — research in the Indian context</a></li><li><a href="https://partners.lenskart.com/" target="_blank" rel="noopener">Lenskart official partner form — owned or rented</a></li></ul><p class="hint">International guidance is used for process design, not represented as Indian law. Published brand criteria vary by format and territory.</p></div></section><section class="panel"><div class="panel-top"><h2>Evidence and eligibility</h2></div><div class="panel-body"><ul class="help-list"><li>Missing or contradictory data stays in the pipeline for clarification.</li><li>Declared investment below the configured requirement is a hold.</li><li>Area below the configured minimum and infeasible launch timing cannot be offset by experience.</li><li>Existing-store pins, one store per pin and territory slots remain mandatory.</li><li>Before an offer, verify funds, funding conditions, working capital, site rights, demand, rent economics and operator fit.</li><li>Financial statements, signed leases, interviews and actual catchment evidence are absent from the uploaded template. They are not inferred.</li></ul><p class="small-text muted">The old 60/10/30 percentile score remains visible in each applicant’s details for comparison. Version 2 uses absolute requirements, so adding an unrelated applicant no longer changes an existing score.</p></div></section></div>`;}
function upload(){return heading('IMPORT APPLICATIONS','Bring your next opportunities in.','Upload the original test format. Incomplete records are welcome.',`<a class="button" href="template.xlsx" download>Download template ↓</a>`)+`<section class="panel"><div class="panel-top"><div><h2>Upload an Excel workbook</h2><div class="panel-subtitle">Applications and Territories · fixed existing-store list stays protected.</div></div><span class="tag gray">.xlsx · up to 10 MB</span></div><div class="panel-body"><div class="dropzone" id="dropzone" tabindex="0" role="button" aria-label="Choose XLSX workbook"><div class="drop-icon">${icon('upload')}</div><h2>Drop your workbook here</h2><p>or click to choose a file from your computer.<br>Your file is processed in your browser.</p><span class="button primary">Choose workbook</span></div><label class="check-line"><input type="checkbox" id="include-examples"> Include row 3 examples from the supplied template</label><p class="hint">The template says row 3 is an example and real entries begin at row 4. Turn this on to test the template’s sample application and territory.</p><div id="import-preview"></div><p class="small-text"><a href="qa-test-data.xlsx" download>Download synthetic stress-test workbook ↓</a> · <a href="qa-rescoring.csv" download>Download initial rescoring results ↓</a></p><div class="info-row">Each import replaces this browser’s current workspace after confirmation. Export a backup first if you want to keep your current work.</div><div class="actions"><button class="button" id="load-demo">Load synthetic demo</button><button class="button" data-demo-workbook="demo-1-clean.xlsx" title="30 applicants and 8 territories with clean data">Load demo 1 (clean)</button><button class="button" data-demo-workbook="demo-2-messy.xlsx" title="31 applicants and 8 territories with deliberate data problems">Load demo 2 (messy)</button><button class="button" id="restore">Restore workspace backup</button></div></div></section>`;}
function modal(content){$('#overlay').innerHTML=`<section class="drawer" role="dialog" aria-modal="true" aria-label="Application workspace">${content}</section>`;$('#overlay').hidden=false;document.body.style.overflow='hidden';$('#overlay').querySelector('button,input,select')?.focus();}
function close(){ $('#overlay').hidden=true;$('#overlay').innerHTML='';document.body.style.overflow='';}
function detail(key){let a=results.find(a=>a.key===key);if(!a)return;let tasks=state.tasks[key]||{},dates=state.taskDates[key]||{};modal(`<div class="drawer-head"><div><span class="eyebrow">${esc(a.id||'ID missing')} · ${esc(a.city||'City missing')}</span><h2>${esc(a.name||'Name missing')}</h2>${statusTag(a)} <span class="sub">${esc(a.status)}</span></div><button class="close" data-close aria-label="Close dialog">×</button></div><div class="detail-score"><div><div class="eyebrow">RECORDED INPUTS TO POSSIBLE SCORE</div><div class="big-score">${a.score}${a.high>a.score?'–'+a.high:''}<small> /100</small></div></div><div><div class="small-text">${a.high>a.score?'Some components remain unknown':'All components scored'}</div><small>Grade ${esc(a.grade)} · proposed screening band<br>Previous percentile-policy score: ${a.legacyScore}/100</small></div></div><section class="panel"><div class="panel-top"><h2>Why this decision?</h2><button class="button small" data-ask-bot="${esc(key)}">Ask bot ↗</button></div><div class="panel-body">${a.reasons.map(r=>`<div class="reason">${esc(r)}</div>`).join('')}<div class="info-row"><strong>Next action:</strong> ${esc(nextAction(a))}</div></div></section><section class="panel"><div class="panel-top"><h2>Score breakdown</h2></div><div class="table-wrap"><table class="breakdown"><thead><tr><th>Component</th><th>Points</th><th>Contribution</th></tr></thead><tbody>${a.components.map(c=>`<tr><td>${esc(c.label)}<span class="sub">${esc(c.detail)}</span></td><td>${c.points===null?'Unknown':c.points+' / '+c.max}</td><td>${c.points===null?'0–'+c.weight:c.contribution.toFixed(1)} / ${c.weight}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-top"><h2>Application details</h2><button class="button small" data-edit="${esc(key)}">Edit application</button></div><div class="panel-body"><div class="form-grid">${E.fields.filter(f=>!['name','id'].includes(f)).map(f=>`<div><span class="hint">${esc(E.labels[f])}</span><div class="small-text">${esc(a[f]??'Missing')}</div></div>`).join('')}</div></div></section><section class="panel"><div class="panel-top"><h2>Opening checklist</h2><span class="tag gray">${completed(a)} / 7</span></div><div class="panel-body"><p class="small-text muted">Training language: ${esc(a.language||'Confirm language before completing training')}. ${a.experience===0?'Add introductory retail practice and supervised store exposure.':'Include brand-specific systems, inventory and customer-service practice.'}</p>${a.status!=='Recommended'?'<div class="info-row warning">Onboarding is paused until the application is recommended again. Resolve its current next action first.</div>':''}${taskDefs.map(([title,desc,owner],i)=>`<div class="task-row ${tasks[i]?'done':''}"><input type="checkbox" data-task="${esc(key)}" data-task-index="${i}" ${tasks[i]?'checked':''} ${a.status!=='Recommended'||(i>0&&!tasks[i-1])||(i===5&&!a.language)?'disabled':''} aria-label="Complete ${title}"><div style="flex:1"><strong>${i+1}. ${title}</strong><p>${desc}</p><label class="hint">Due date <input class="input" style="font-size:10px;min-height:26px;padding:4px" type="date" data-task-date="${esc(key)}" data-task-index="${i}" value="${esc(dates[i]||'')}" aria-label="Due date for ${title}"></label>${i===5?`<label class="hint">Hours on LMS <input class="input" style="font-size:10px;min-height:26px;padding:4px;width:80px" type="number" min="0" max="500" step="0.5" data-lms-hours="${esc(key)}" value="${esc(state.training?.[key]??'')}" aria-label="Hours spent on the learning system"></label>`:''}${state.taskDone?.[key]?.[i]?`<span class="hint">Completed ${esc(new Date(state.taskDone[key][i]).toLocaleDateString())}</span>`:''}</div></div>`).join('')}</div></section><details class="small-text muted"><summary>Original imported values</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(JSON.stringify(a.raw,null,2))}</pre></details>`);}
function edit(key){let a=state.apps.find(a=>a.key===key);if(!a)return;let choices={city:Object.keys(E.cities),state:['Karnataka'],space:['Owned','Rented','Not yet identified'],floor:['Ground','Upper','Mall unit','Not known','First','Other confirmed'],language:['Kannada','English','Hindi']};modal(`<div class="drawer-head"><div><div class="eyebrow">CONFIRM AN UPDATE</div><h2>Edit ${esc(a.id||'application')}</h2></div><button class="close" data-close aria-label="Close dialog">×</button></div><p class="small-text muted">Changes update the assessment and territory allocation. Original imported values are retained.</p><form id="edit-form" data-key="${esc(key)}"><div class="form-grid">${E.fields.map(f=>`<label class="${f==='notes'||f==='business'?'full':''}">${esc(E.labels[f])}${choices[f]?`<select class="input" name="${f}"><option value="">Missing / unconfirmed</option>${choices[f].map(c=>`<option value="${esc(c)}" ${a[f]===c?'selected':''}>${esc(c)}</option>`).join('')}</select>`:f==='notes'||f==='business'?`<textarea class="input" name="${f}">${esc(a[f])}</textarea>`:`<input class="input" name="${f}" ${E.numeric.includes(f)?'type="number" min="0" step="any"':''} value="${esc(a[f])}" ${f==='pin'?'inputmode="numeric" maxlength="6"':''}>`}</label>`).join('')}</div><div class="actions section-gap"><button class="button primary">Confirm changes & reassess</button><button type="button" class="button" data-detail="${esc(key)}">Cancel</button></div></form>`);}
function applyPatch(key,patch,why){let a=state.apps.find(a=>a.key===key);if(!a)return;let before=results.find(x=>x.key===key);pendingChat=null;let changed=Object.fromEntries(Object.entries(patch).filter(([k,v])=>a[k]!==v));state.tasks[key]=E.invalidateTasks(state.tasks[key]||{},changed);Object.assign(a,patch);a.pending=a.pending.filter(p=>!(p.field in patch));calculate();let after=results.find(x=>x.key===key);audit(`${a.id||a.key}: ${why}. ${before?.status} → ${after.status}; score ${before?.score} → ${after.score}.`);save();render();return {before,after};}
function explanation(a){return `${a.id} · ${a.name||'Name missing'}\n${a.status} · Score ${a.score}${a.high>a.score?'–'+a.high:''}/100\n\n${a.reasons.join('\n')}\n\nNext action: ${nextAction(a)}.\n\n${a.components.map(c=>`${c.label}: ${c.points===null?'unknown':c.points+'/'+c.max+' points'} (${c.points===null?'0–'+c.weight:c.contribution.toFixed(1)} of ${c.weight})`).join('\n')}`;}
function attachNavigationActions(){const log=$('#chat-log');if(!log)return;const bubbles=[...log.querySelectorAll('.message')];chat.forEach((message,index)=>{const action=message.navigation;if(action?.type!=='navigate'||action.execute!==false)return;const bubble=bubbles[index];if(!bubble||bubble.querySelector('[data-bot-navigation]'))return;const button=document.createElement('button');button.type='button';button.className='button small bot-navigation-action';button.dataset.botNavigation='';button.dataset.botRoute=action.route;button.dataset.botSection=action.sectionId||'';button.dataset.botLabel=action.label||'';button.dataset.botApplicant=action.context?.applicant||'';button.dataset.botSearch=action.context?.searchQuery||'';button.textContent=`Open ${action.label||'section'} ↗`;bubble.append(button);});}
function send(text){if(!text.trim())return;chat.push({text,user:true});pendingChat=null;let response=FranchiseBot.answer(text,{state,results,stores,contextKey:botContext});botContext=response.contextKey||null;chat.push({text:response.text,...(response.navigation?{navigation:response.navigation}:{})});pendingChat=response.proposal||null;chat=chat.slice(-100);save();render();attachNavigationActions();$('#chat-log').scrollTop=$('#chat-log').scrollHeight;}
function download(name,text,type){let blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function exportModal(){modal(`<div class="drawer-head"><h2>Save your results</h2><button class="close" data-close aria-label="Close dialog">×</button></div><p class="small-text muted">This workspace is stored in this browser. Use a backup to continue on another device.</p><div class="actions"><button class="button primary" id="export-csv">Download assessment CSV</button><button class="button" id="export-json">Download workspace backup</button><button class="button" id="restore">Restore a backup</button></div><div class="info-row">CSV includes decisions and next actions. JSON preserves applications, corrections, rules, frozen benchmarks, tasks and activity.</div>`);}
// Demo workbooks ship with the app and go through the same import preview as an upload, so the user confirms the replacement.
async function loadWorkbookDemo(name){if(!confirm('Load '+name.replace(/\.xlsx$/,'').replace(/-/g,' ')+' as an import preview? Confirming replaces this browser’s workspace.'))return;try{const response=await fetch('demo/'+name);if(!response.ok)throw Error('Demo workbook not found.');const blob=await response.blob();tab='upload';location.hash='upload';render();await parseFile(new File([blob],name,{type:blob.type}));}catch(error){toast(error.message||'The demo workbook could not be loaded.');}}
async function parseFile(file){if(!file)return;importPreview=null;if($('#import-preview'))$('#import-preview').innerHTML='';try{toast('Reading workbook…');let sheets=await WorkbookReader.readWorkbook(file),include=$('#include-examples')?.checked||false;let parsed=WorkbookReader.importRows(sheets,include,stores);importPreview={...parsed,source:file.name};$('#import-preview').innerHTML=`<div class="info-row"><strong>${esc(file.name)}</strong><br>${parsed.apps.length} applications · ${parsed.territories.length} territories · ${parsed.apps.reduce((n,a)=>n+a.pending.length,0)} proposed corrections</div>${parsed.warnings.length?`<div class="info-row warning">${parsed.warnings.map(esc).join('<br>')}</div>`:''}<button id="confirm-import" class="button primary" ${!parsed.apps.length?'disabled':''}>Replace workspace & import</button>`;toast('Workbook read. Review the summary before importing.');}catch(e){toast(e.message||'The workbook could not be read.');}$('#file').value='';}
// Sample onboarding progress that ships with the demo, so the overview's onboarding and LMS figures have data.
function seedDemoOnboarding(data){for(const o of data.onboarding||[]){const app=state.apps.find(x=>x.id===o.id);if(!app)continue;state.tasks[app.key]=Object.fromEntries(o.completed.map((_,i)=>[i,true]));state.taskDone={...state.taskDone,[app.key]:Object.fromEntries(o.completed.map((day,i)=>[i,day+'T10:00:00.000Z']))};if(Number.isFinite(o.lmsHours))state.training={...state.training,[app.key]:o.lmsHours};}}
// Demo workspaces saved before Oct 2026 used PINs that are not in the India Post directory; move them to real PINs once.
const DEMO_PIN_FIXES={'560101':'560048','570101':'570010','570102':'570011','570103':'570020','575101':'575002','575102':'575003','575103':'575004','580101':'580029','580102':'580030','580103':'580031','590101':'590006','590102':'590010','590103':'590016','577101':'577001','577102':'577002','577103':'577004'};
async function migrateDemoWorkspace(){if(!isDemo())return;let changed=false;for(const a of state.apps){const next=DEMO_PIN_FIXES[a.pin];if(next){a.pin=next;if(a.raw&&typeof a.raw==='object'&&'pin' in a.raw)a.raw.pin=next;changed=true;}}for(const t of state.territories){const pins=t.pins.map(p=>DEMO_PIN_FIXES[p]||p);if(pins.some((p,i)=>p!==t.pins[i])){t.pins=pins;changed=true;}}if(changed)audit('Demo territories now use real India Post PINs, so their population and TAM load.');if(!state.taskDone){try{seedDemoOnboarding(await(await fetch('demo.json')).json());changed=true;}catch{}}if(changed){save();render();}}
async function loadDemo(initial=false){try{let data=await(await fetch('demo.json')).json();pendingChat=null;chat=[];botContext=null;state={apps:data.apps.map((a,i)=>E.normalize(a,'demo-'+i)),territories:data.territories,reference:null,settings:{...E.defaultPolicy},tasks:{},taskDates:{},audit:[],source:'Synthetic demo · 24 applicants',warnings:[]};state.reference=E.benchmarks(state.apps);seedDemoOnboarding(data);state.reference=E.benchmarks(state.apps);audit('Loaded synthetic demo data. These are fictional applicants.');save();tab=initial?(location.hash.slice(1)||'overview'):'overview';location.hash=tab;render();if(!initial)toast('Synthetic demo loaded.');}catch(e){toast('Could not load demo. Upload a workbook to get started.');render();}}
function bindPage(){if($('#search'))$('#search').oninput=e=>{query=e.target.value;let pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};if($('#status-filter'))$('#status-filter').onchange=e=>{filter=e.target.value;render();};if($('#chat-form'))$('#chat-form').onsubmit=e=>{e.preventDefault();send($('#chat-text').value);};if($('#dropzone')){let d=$('#dropzone');d.onclick=()=>$('#file').click();d.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#file').click();}};d.ondragover=e=>{e.preventDefault();d.classList.add('drag');};d.ondragleave=()=>d.classList.remove('drag');d.ondrop=e=>{e.preventDefault();d.classList.remove('drag');parseFile(e.dataTransfer.files[0]);};}}
document.addEventListener('click',e=>{let el=e.target.closest('button,a,tr[data-detail]');if(!el)return;let d=el.dataset;if(el.id==='demo-toggle'){setDemoHidden(!demoHidden());return;}if(d.showDemo!==undefined){setDemoHidden(false);return;}if(d.demoWorkbook){loadWorkbookDemo(d.demoWorkbook);return;}if(d.miSaved){const saved=marketAssessments.find(a=>a.id===d.miSaved);if(saved){marketNewDraft=false;marketAnalyzed=true;marketResult=saved.snapshot?.results||null;marketSelectedLocation=saved.snapshot?.selectedLocation||{name:saved.snapshot?.location?.city||saved.snapshot?.location?.state||saved.snapshot?.location?.pin||'Saved location',level:saved.snapshot?.location?.pin?'pin':saved.snapshot?.location?.city?'city':'state',...saved.snapshot?.location};document.body.dataset.marketAssessment=saved.id;render();}return;}if(d.screenPin){const place={id:`pin:${d.screenPin}`,name:d.screenPin,level:'pin',pin:d.screenPin};chooseScreeningLocation(place);return;}if(el.id==='market-new'){marketQueryDraft='';delete document.body.dataset.marketAssessment;marketResult=null;marketPinStatus='';marketSelectedLocation=null;marketAnalyzed=false;marketNewDraft=true;render();return;}if(el.id==='market-compare'){compareMarket();return;}if(el.id==='market-forecast'){runMarketForecast();return;}if(d.marketBenchmark!==undefined){const b=marketBenchmarks[Number(d.marketBenchmark)],form=$('#market-form');if(b&&form){form.elements.regionalSpend.value=b.value;form.elements.state.value=b.geography?.state||form.elements.state.value;form.dataset.benchmark=String(d.marketBenchmark);toast(`Loaded official survey benchmark: ${b.evidenceClass}, ${b.referencePeriod}, ${b.geography?.level} ${b.geography?.sector||''}.`);}return;}if(d.askBot){close();botContext=d.askBot;tab='assistant';location.hash=tab;render();let a=results.find(a=>a.key===botContext);send('Why is '+a.id+' '+a.status+'?');}else if(d.tab){const next=d.tab;if(next!==tab){tab=next;render();if(window.location.hash!=='#'+tab)window.location.hash=tab;if(['market','screening'].includes(tab))loadMarket();}return;}else if(d.filter){filter=d.filter;query='';tab='applications';location.hash=tab;render();}else if(d.detail)detail(d.detail);else if(d.edit)edit(d.edit);else if('close'in d)close();else if(d.prompt)send(d.prompt);else if(el.id==='clear-chat'){pendingChat=null;chat=[];botContext=null;save();render();}else if(d.confirmCorrection){let a=state.apps.find(a=>a.key===d.confirmCorrection),p=a.pending[Number(d.index)],v=document.getElementById('correction-'+a.key+'-'+d.index).value;if(v===''||!Number.isFinite(Number(v))||Number(v)<0){toast('Enter a valid non-negative number to confirm.');return;}state.corrections=(state.corrections||0)+1;applyPatch(a.key,{[p.field]:Number(v)},`Confirmed ${E.labels[p.field]}: ${p.raw} → ${v}`);toast('Correction confirmed. Application reassessed.');}else if(d.rejectCorrection){let a=state.apps.find(a=>a.key===d.rejectCorrection),p=a.pending[Number(d.index)];applyPatch(a.key,{[p.field]:null},`Marked ${E.labels[p.field]} as missing`);}else if(el.id==='load-demo'){if(confirm('Replace this browser’s workspace with synthetic demo data? Export a backup first if needed.'))loadDemo();}else if(el.id==='restore')$('#restore-file').click();else if(el.id==='export')exportModal();else if(el.id==='export-json')download('franchise-workspace.json',JSON.stringify({version:1,state},null,2),'application/json');else if(el.id==='export-csv'){const safe=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};let rows=[['Application ID','Name','City','Pin','Status','Recorded-input score','Possible score','Grade','Model','Legacy score','Territory','Reason','Next action'],...results.map(a=>[a.id,a.name,a.city,a.pin,a.status,a.score,a.high,a.grade,a.model,a.legacyScore,a.territory,a.reasons.join(' '),nextAction(a)])];download('franchise-assessments.csv','\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8');}else if(el.id==='rebase'){if(confirm('Rebuild percentile references? This may change every applicant’s score and allocation.')){pendingChat=null;state.reference=E.benchmarks(state.apps);audit('Rebuilt percentile references using currently confirmed data.');save();render();toast('References rebuilt. Scores and allocations updated.');}}else if(el.id==='confirm-chat'){let p=pendingChat;let current=p&&state.apps.find(a=>a.key===p.key);if(!current||JSON.stringify(E.fields.map(f=>current[f]))!==p.snapshot){pendingChat=null;chat.push({text:'The application changed after this proposal. Please describe the update again so I can assess the current data.'});render();return;}pendingChat=null;let r=applyPatch(p.key,p.patch,'Confirmed bot update: '+Object.keys(p.patch).map(f=>E.labels[f]).join(', '));chat.push({text:`Confirmed ${p.id}.\n${r.before.status} → ${r.after.status}; confirmed score ${r.before.score} → ${r.after.score}.\n\n${r.after.reasons.join('\n')}`});save();render();$('#chat-log').scrollTop=$('#chat-log').scrollHeight;}else if(el.id==='cancel-chat'){pendingChat=null;chat.push({text:'Update cancelled. Application retained as it was.'});save();render();}else if(el.id==='confirm-import'&&importPreview){let p=importPreview;pendingChat=null;chat=[];botContext=null;state={apps:p.apps,territories:p.territories,reference:E.benchmarks(p.apps),settings:{...E.defaultPolicy},tasks:{},taskDates:{},audit:[],source:p.source,warnings:p.warnings};audit(`Imported ${p.apps.length} applications and ${p.territories.length} territories from ${p.source}.`);save();importPreview=null;tab=pendingCount()?'review':'applications';location.hash=tab;filter='';query='';render();toast('Import complete. Every application is retained.');}else if(el.id==='help'){modal(`<div class="drawer-head"><h2>Your expansion workspace</h2><button class="close" data-close aria-label="Close dialog">×</button></div><ol class="help-list"><li>Upload the supplied XLSX format. Row 3 examples are excluded unless selected.</li><li>Confirm proposed cleaning and fill missing fields.</li><li>Review scores and territory recommendations.</li><li>Ask the assistant for a reason or confirm a field update.</li><li>Verify funding, inspect the site and track opening readiness.</li></ol><div class="info-row">Data stays in this browser. Export a JSON backup to preserve your work or use another device. Other visitors have separate workspaces. The assistant uses supported rules and patterns; it does not call an external AI model.</div>`);}});
document.addEventListener('submit',e=>{if(e.target.id==='market-form'){e.preventDefault();submitMarket(e.target);return;}if(e.target.id!=='edit-form')return;e.preventDefault();let form=e.target,patch=Object.fromEntries(new FormData(form));for(let f of E.numeric)patch[f]=patch[f]===''?null:Number(patch[f]);for(let f of E.fields)if(!E.numeric.includes(f))patch[f]=patch[f].trim()||null;applyPatch(form.dataset.key,patch,'Confirmed application details');detail(form.dataset.key);toast('Application updated. All affected allocations reassessed.');});
document.addEventListener('change',e=>{let d=e.target.dataset;if(e.target.id==='sector-select'){switchSector(e.target.value);return;}if(d.lmsHours){const hours=Number(e.target.value);state.training??={};if(e.target.value===''||!Number.isFinite(hours)||hours<0)delete state.training[d.lmsHours];else state.training[d.lmsHours]=hours;save();return;}if(d.task){let key=d.task,i=Number(d.taskIndex);state.tasks[key]??={};state.tasks[key][i]=e.target.checked;state.taskDone??={};state.taskDone[key]??={};if(e.target.checked)state.taskDone[key][i]=new Date().toISOString();else for(let j=i;j<7;j++)delete state.taskDone[key][j];if(!e.target.checked)for(let j=i+1;j<7;j++)state.tasks[key][j]=false;audit(`${state.apps.find(a=>a.key===key)?.id}: ${taskDefs[i][0]} ${e.target.checked?'completed':'reopened; later steps reset'}.`);save();render();detail(key);}else if(d.taskDate){state.taskDates[d.taskDate]??={};state.taskDates[d.taskDate][d.taskIndex]=e.target.value;save();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();let r=e.target.closest('tr[data-detail]');if(r&&e.key==='Enter')detail(r.dataset.detail);if(e.key==='Tab'&&!$('#overlay').hidden){let f=[...$('#overlay').querySelectorAll('button,input,select,textarea,a[href],summary')].filter(x=>!x.disabled&&x.offsetParent!==null);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0]?.focus();}}});
$('#overlay').onclick=e=>{if(e.target===$('#overlay'))close();};$('#file').onchange=e=>parseFile(e.target.files[0]);$('#restore-file').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>10000000)throw Error('Backup is too large.');let p=JSON.parse(await f.text());if(p.version!==1||!E.validState(p.state))throw Error('This is not a valid FranchiseOS backup.');E.assess(p.state.apps,p.state.territories,stores,p.state.reference,p.state.settings);if(!confirm('Replace this browser’s workspace with the backup?'))return;pendingChat=null;chat=[];botContext=null;state=p.state;if(state.settings.model!=='industry-v2')state.settings={...E.defaultPolicy,...Object.fromEntries(Object.entries(state.settings).filter(([k,v])=>v!=='')),model:'industry-v2'};state.taskDates??={};state.tasks??={};state.audit??=[];state.warnings??=[];audit('Restored workspace from a JSON backup.');save();close();tab='overview';location.hash=tab;render();toast('Backup restored.');}catch(err){toast(err.message||'Backup could not be restored.');}e.target.value='';};
window.addEventListener('franchiseos:location-selected',handleSharedLocation);
document.addEventListener('click',event=>{if(!event.target.closest('#currency-toggle,[data-map-currency-toggle]'))return;const next=window.FranchiseDisplay?.getMode()==='millions'?'crores':'millions';window.FranchiseDisplay?.setMode(next);});
window.addEventListener('franchiseos:currency-display-changed',()=>{const label=window.FranchiseDisplay?.toggleLabel()||'₹ Millions';document.querySelectorAll('#currency-toggle,[data-map-currency-toggle]').forEach(button=>button.textContent=label);marketUi?.refreshDisplay?.();territoryScreening?.refreshDisplay?.();expansionMap?.refreshDisplay?.();});
if($('#currency-toggle'))$('#currency-toggle').textContent=window.FranchiseDisplay?.toggleLabel()||'₹ Millions';
const botRoutes=new Set(['overview','applications','review','territories','screening','market','expansion','onboarding','assistant','rules','upload']);
window.addEventListener('franchiseos:navigate',event=>{const action=event.detail;if(!action||action.type!=='navigate'||action.execute!==false||!botRoutes.has(action.route))return;if(action.route==='market'&&action.context?.searchQuery){marketQueryDraft=action.context.searchQuery;marketSelectedLocation=null;marketAnalyzed=false;marketNewDraft=true;}tab=action.route;location.hash=tab;render();if(['market','screening'].includes(tab))loadMarket();const headingNode=$('#main .page-heading');if(headingNode){headingNode.style.outline='2px solid #7aa58c';headingNode.style.outlineOffset='6px';headingNode.scrollIntoView?.({behavior:'smooth',block:'start'});}const key=action.context?.applicant;if(key&&tab==='onboarding'){const row=[...document.querySelectorAll('#main [data-detail]')].find(element=>element.dataset.detail===key);if(row){row.style.outline='2px solid #7aa58c';row.style.outlineOffset='4px';row.click();}}});
document.addEventListener('click',event=>{const button=event.target.closest('[data-bot-navigation]');if(!button)return;const action={type:'navigate',route:button.dataset.botRoute,sectionId:button.dataset.botSection,label:button.dataset.botLabel,execute:false,permission:'read',context:{applicant:button.dataset.botApplicant||null,searchQuery:button.dataset.botSearch||null}};window.dispatchEvent(new CustomEvent('franchiseos:navigate',{detail:action}));});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'overview';if(next===tab)return;tab=next;render();if(['market','screening'].includes(tab))loadMarket();});
(async()=>{try{const saved=await persistence.load();if(saved&&E.validState(saved)){state=saved;if(state.settings.model!=='industry-v2'){state.settings={...E.defaultPolicy,...Object.fromEntries(Object.entries(state.settings).filter(([k,v])=>v!=='')),model:'industry-v2'};audit('Rescored with industry-informed v2 screening using the labelled illustrative retail requirements.');}state.taskDates??={};chat=Array.isArray(state.messages)?state.messages:[];botContext=state.botContext||null;tab=location.hash.slice(1)||'overview';render();updateStorageBadge();if(['market','screening'].includes(tab))loadMarket();void migrateDemoWorkspace();return;}}catch(e){storageOK=false;}await loadDemo(true);updateStorageBadge();if(['market','screening'].includes(tab))loadMarket();})();
// Franchise bot drawer: answers from the current page without navigating (see chat-widget.js).
if(window.FranchiseChat&&$('.bot-launcher'))FranchiseChat.mount({launcher:$('.bot-launcher'),provider:()=>({tab,state,results,stores,botContext}),app:{setBotContext:key=>{botContext=key||null;},navigate:action=>window.dispatchEvent(new CustomEvent('franchiseos:navigate',{detail:action})),confirmProposal(p){const current=p&&state.apps.find(a=>a.key===p.key);if(!current||JSON.stringify(E.fields.map(f=>current[f]))!==p.snapshot)return {error:'The application changed after this proposal. Please describe the update again so I can assess the current data.'};const r=applyPatch(p.key,p.patch,'Confirmed bot update: '+Object.keys(p.patch).map(f=>E.labels[f]).join(', '));return {text:`Confirmed ${p.id}.\n${r.before.status} → ${r.after.status}; confirmed score ${r.before.score} → ${r.after.score}.\n\n${r.after.reasons.join('\n')}`};}}});
